import sys

def solve():
    T = int(sys.stdin.readline())
    for _ in range(T):
        n = int(sys.stdin.readline())
        a = list(map(int, sys.stdin.readline().split()))
        sorted_a = sorted(a)
        pos = {v: i for i, v in enumerate(sorted_a)}
        valid = True
        for i in range(n):
            if abs(i - pos[a[i]]) > 1:
                valid = False
                break
        print("YES" if valid else "NO")

solve()
